// Builds db/dist/floodlight_bundle.sql from db/migrations/*.sql.
//
// The bundle is safe to run more than once: each migration is applied only if
// its version is not yet in floodlight_private.schema_migrations (Floodlight's
// OWN ledger). It never writes to supabase_migrations.schema_migrations, so the
// shared project's Supabase CLI history (owned by EKSU Sports Hub) is
// untouched. The whole bundle runs in one transaction: any error rolls back
// every Floodlight change.
//
//   node scripts/build-db-bundle.mjs
import { readdirSync, readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { createHash } from "node:crypto";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const dir = join(root, "db/migrations");
const files = readdirSync(dir).filter((f) => /^\d{4}_.+\.sql$/.test(f)).sort();

let out = `-- GENERATED by scripts/build-db-bundle.mjs — do not edit by hand.
-- EKSU Floodlight database bundle (${files.length} migrations).
-- Target: a Supabase project shared with EKSU Sports Hub. Touches only the
-- floodlight / floodlight_private schemas, plus: btree_gist extension,
-- storage bucket + 3 bucket-scoped storage policies, one pg_cron job.
begin;

create schema if not exists floodlight_private;
create table if not exists floodlight_private.schema_migrations (
  version text primary key,
  name text not null,
  checksum text not null,
  applied_at timestamptz not null default now()
);
revoke all on floodlight_private.schema_migrations from public;
`;

for (const f of files) {
  const sql = readFileSync(join(dir, f), "utf8");
  const version = f.slice(0, 4);
  const checksum = createHash("sha256").update(sql).digest("hex");
  const tag = `$fl_${version}$`;
  const outer = `$fl_do_${version}$`;
  if (sql.includes(tag) || sql.includes(outer)) throw new Error(`${f} contains a reserved dollar-quote tag`);
  out += `
-- ===== ${f} =====
do ${outer}
declare v_existing text;
begin
  select checksum into v_existing from floodlight_private.schema_migrations where version = '${version}';
  if v_existing is not null then
    if v_existing <> '${checksum}' then
      raise exception 'Floodlight migration ${f} was already applied with different contents';
    end if;
    raise notice 'skip ${f} (already applied)';
    return;
  end if;
  execute ${tag}${sql}${tag};
  insert into floodlight_private.schema_migrations (version, name, checksum) values ('${version}', '${f}', '${checksum}');
  raise notice 'applied ${f}';
end ${outer};
`;
}

out += `
-- Make the new schema visible to the Data API without a restart.
notify pgrst, 'reload schema';
commit;
`;

mkdirSync(join(root, "db/dist"), { recursive: true });
writeFileSync(join(root, "db/dist/floodlight_bundle.sql"), out);
console.log(`db/dist/floodlight_bundle.sql: ${files.length} migrations, ${out.length} bytes`);
